// CPU fallback for devices/browsers without WebGL. Same 3D geometry and game state.
import {Matrix4,Vector3,Color} from './vendor/three.js';
export class SoftwareRenderer{
 constructor(canvas,alpha=false){this.software=true;this.domElement=canvas;this.ctx=canvas.getContext('2d',{alpha});this.alpha=alpha;this.shadowMap={};this.info={render:{calls:0,triangles:0},memory:{geometries:0,textures:0}};this.w=1;this.h=1;this.ratio=.65;this.cache=new WeakMap();}
 setPixelRatio(){this.ratio=.65;}
 setSize(w,h){this.w=w;this.h=h;this.domElement.width=Math.round(w*this.ratio);this.domElement.height=Math.round(h*this.ratio);}
 dispose(){}
 render(scene,camera){const ctx=this.ctx,w=this.domElement.width,h=this.domElement.height;scene.updateMatrixWorld();camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const vp=new Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),triangles=[],cam=camera.position;let count=0;
 ctx.clearRect(0,0,w,h);if(!this.alpha){ctx.fillStyle=scene.background?.getStyle()||'#aedfeb';ctx.fillRect(0,0,w,h);}const sun=new Vector3(-.4,.8,.4).normalize();
 scene.traverseVisible(o=>{if(!o.isMesh)return;const g=o.geometry,a=g.attributes.position;if(!a)return;const material=o.material;if(Array.isArray(material)||material.wireframe)return;const idx=g.index?.array,nn=idx?idx.length:a.count;const instances=o.isInstancedMesh?o.count:1;
 for(let inst=0;inst<instances;inst++){let mw=o.matrixWorld;if(o.isInstancedMesh){const im=new Matrix4();o.getMatrixAt(inst,im);mw=new Matrix4().multiplyMatrices(o.matrixWorld,im);}const mvp=new Matrix4().multiplyMatrices(vp,mw),e=mvp.elements,me=mw.elements;const projected=new Float32Array(a.count*4),world=new Float32Array(a.count*3);for(let i=0;i<a.count;i++){const x=a.getX(i),y=a.getY(i),z=a.getZ(i),ww=e[3]*x+e[7]*y+e[11]*z+e[15];projected[i*4]=(e[0]*x+e[4]*y+e[8]*z+e[12])/ww*w/2+w/2;projected[i*4+1]=-(e[1]*x+e[5]*y+e[9]*z+e[13])/ww*h/2+h/2;projected[i*4+2]=ww;world[i*3]=me[0]*x+me[4]*y+me[8]*z+me[12];world[i*3+1]=me[1]*x+me[5]*y+me[9]*z+me[13];world[i*3+2]=me[2]*x+me[6]*y+me[10]*z+me[14];}
 const color=material.color||new Color(0xffffff);let srgb=color.clone().convertLinearToSRGB();const rgb=[srgb.r*255,srgb.g*255,srgb.b*255];for(let j=0;j<nn;j+=3){const ia=idx?idx[j]:j,ib=idx?idx[j+1]:j+1,ic=idx?idx[j+2]:j+2;const ax=projected[ia*4],ay=projected[ia*4+1],bx=projected[ib*4],by=projected[ib*4+1],cx=projected[ic*4],cy=projected[ic*4+1];if(projected[ia*4+2]<.2||projected[ib*4+2]<.2||projected[ic*4+2]<.2)continue;if(Math.max(ax,bx,cx)<0||Math.min(ax,bx,cx)>w||Math.max(ay,by,cy)<0||Math.min(ay,by,cy)>h)continue;const cross=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax);if(material.side!==2&&cross>0)continue;if(Math.abs(cross)<.7)continue;
 const ux=world[ib*3]-world[ia*3],uy=world[ib*3+1]-world[ia*3+1],uz=world[ib*3+2]-world[ia*3+2],vx=world[ic*3]-world[ia*3],vy=world[ic*3+1]-world[ia*3+1],vz=world[ic*3+2]-world[ia*3+2];let nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx;const len=Math.hypot(nx,ny,nz)||1;const light=material.isMeshBasicMaterial?1:.65+.35*Math.max(0,(nx*sun.x+ny*sun.y+nz*sun.z)/len);const depth=(projected[ia*4+2]+projected[ib*4+2]+projected[ic*4+2])/3;if(depth>260&&o.renderOrder>=0)continue;let col=rgb.map(c=>Math.round(c*light));if(scene.fog){const f=Math.max(0,Math.min(.9,(depth-scene.fog.near)/(scene.fog.far-scene.fog.near)));const fc=scene.fog.color.clone().convertLinearToSRGB();col=col.map((c,i)=>Math.round(c*(1-f)+[fc.r,fc.g,fc.b][i]*255*f));}triangles.push({ax,ay,bx,by,cx,cy,depth,order:o.renderOrder,color:`rgb(${col})`,alpha:material.opacity??1});}
 count++;}});
 triangles.sort((a,b)=>a.order-b.order||b.depth-a.depth);for(const t of triangles){ctx.globalAlpha=t.alpha;ctx.fillStyle=t.color;ctx.beginPath();ctx.moveTo(t.ax,t.ay);ctx.lineTo(t.bx,t.by);ctx.lineTo(t.cx,t.cy);ctx.closePath();ctx.fill();if(t.order<0){ctx.strokeStyle=t.color;ctx.lineWidth=.7;ctx.stroke();}}ctx.globalAlpha=1;this.info.render={calls:count,triangles:triangles.length};}
}
